import React from "react";
import AnimateOnScroll from "./AnimateOnScroll";

const HeroHeader = () => {
  return (
    <AnimateOnScroll 
      tag="div" 
      className="home-header-container1" 
      duration={1}
    >
      <div className="home-header11">
        <h1>
          Performance Intelligence <br />
          <span className="gradient-text">Platform</span>
        </h1>
      </div>
      <p className="home-caption10">
        Empowering Sports organisations and their athletes to reach their peak performance
        through digitization, Sports Science & Artificial Intelligence.
      </p>
    </AnimateOnScroll>
  );
};

export default HeroHeader;
